#!/usr/bin/env bash
# Autonomously generated by an AI agent.
set -Eeuo pipefail

stage=arguments
installation_failed() {
    local result=$?
    printf 'Mixxx installation failed during %s (exit %s).\n' "$stage" "$result" >&2
    exit "$result"
}
trap installation_failed ERR

usage() {
    cat <<'HELP'
Usage: tools/install-linux.sh [options]

Install native dependencies, configure, build, test and install this checkout.
Automatic dependencies: Debian 13+, Ubuntu 24.04+, compatible derivatives.
Other Linux distributions can use --no-deps with an existing native toolchain.

  --prefix PATH       Installation prefix (default: $HOME/.local)
  --build-dir PATH    Build directory (default: CHECKOUT/build-linux)
  --jobs N            Parallel jobs (default: CPU/memory allowance, capped at 4)
  --no-deps           Skip native package installation
  --no-tests          Disable building/running unit tests
  --dry-run           Print the plan; do not install, create directories or build
  -h, --help          Show this help

Relative paths are resolved from the caller's current directory. Existing build
directories retain their CMake generator. Package/system-prefix operations need
root or noninteractive sudo; building/testing always uses the current user.
HELP
}

die() {
    printf 'Error: %s\n' "$*" >&2
    exit 2
}

need_value() {
    [[ $# -ge 2 && -n $2 && $2 != --* ]] || die "$1 requires a value"
}

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
repo_root=$(cd -- "$script_dir/.." && pwd -P)
build_dir="$repo_root/build-linux"
install_prefix=
jobs=
install_dependencies=true
run_tests=true
dry_run=false
while (($#)); do
    case "$1" in
        --prefix) need_value "$@"; install_prefix=$2; shift 2 ;;
        --build-dir) need_value "$@"; build_dir=$2; shift 2 ;;
        --jobs) need_value "$@"; jobs=$2; shift 2 ;;
        --no-deps) install_dependencies=false; shift ;;
        --no-tests) run_tests=false; shift ;;
        --dry-run) dry_run=true; shift ;;
        -h|--help) usage; exit 0 ;;
        *) die "unknown argument: $1" ;;
    esac
done

[[ $(uname -s) == Linux ]] || die 'this installer supports Linux only'
[[ -f "$repo_root/CMakeLists.txt" && -f "$repo_root/tools/debian_buildenv.sh" ]] ||
    die 'run the installer from an intact Mixxx source checkout'
command -v realpath >/dev/null || die 'realpath from GNU coreutils is required'
if [[ -z $install_prefix ]]; then
    [[ -n ${HOME:-} ]] || die 'HOME is unset; pass --prefix explicitly'
    install_prefix="$HOME/.local"
fi
build_dir=$(realpath -m -- "$build_dir")
install_prefix=$(realpath -m -- "$install_prefix")
[[ $build_dir != "$repo_root" && $build_dir != / ]] || die 'use an out-of-source build directory'
[[ $install_prefix != / && $install_prefix != "$repo_root" ]] || die 'unsafe installation prefix'
[[ ! -e $install_prefix || -d $install_prefix ]] || die 'installation prefix is not a directory'
if [[ -f "$build_dir/CMakeCache.txt" ]]; then
    cached_source=$(sed -n 's/^CMAKE_HOME_DIRECTORY:INTERNAL=//p' "$build_dir/CMakeCache.txt")
    [[ -z $cached_source || $(realpath -m -- "$cached_source") == "$repo_root" ]] ||
        die 'the selected build directory belongs to another source checkout'
fi

if [[ -z $jobs ]]; then
    jobs=$(getconf _NPROCESSORS_ONLN 2>/dev/null || printf '2')
    [[ $jobs =~ ^[1-9][0-9]*$ ]] || jobs=2
    ((jobs <= 4)) || jobs=4
    memory_kb=$(awk '/^MemAvailable:/ {print $2; exit}' /proc/meminfo 2>/dev/null || true)
    if [[ $memory_kb =~ ^[0-9]+$ && ${#memory_kb} -le 15 ]]; then
        memory_budget=$((10#$memory_kb * 1024))
        for limit_file in /sys/fs/cgroup/memory.max /sys/fs/cgroup/memory/memory.limit_in_bytes; do
            if [[ -r $limit_file ]]; then
                cgroup_limit=$(< "$limit_file")
                if [[ $cgroup_limit =~ ^[0-9]+$ && ${#cgroup_limit} -le 18 ]] &&
                        ((10#$cgroup_limit < memory_budget)); then
                    memory_budget=$((10#$cgroup_limit))
                fi
            fi
        done
        memory_jobs=$((memory_budget / 2147483648))
        ((memory_jobs >= 1)) || memory_jobs=1
        ((jobs <= memory_jobs)) || jobs=$memory_jobs
    fi
fi
[[ $jobs =~ ^[1-9][0-9]*$ && ${#jobs} -le 3 ]] || die '--jobs must be an integer from 1 to 256'
((jobs <= 256)) || die '--jobs must be an integer from 1 to 256'

run() {
    printf '+'
    printf ' %q' "$@"
    printf '\n'
    if ! $dry_run; then
        "$@"
    fi
}

root_command=()
require_root_command() {
    if ((EUID == 0)); then
        root_command=()
    elif $dry_run || command -v sudo >/dev/null; then
        root_command=(sudo -n '--preserve-env=http_proxy,https_proxy,HTTP_PROXY,HTTPS_PROXY,no_proxy,NO_PROXY')
    else
        die 'this operation needs root or sudo; use --no-deps and a writable --prefix when dependencies exist'
    fi
}

available_package() {
    apt-cache show "$1" >/dev/null 2>&1
}

package_alias() {
    local candidate
    for candidate in "$@"; do
        if available_package "$candidate"; then
            printf '%s\n' "$candidate"
            return
        fi
    done
    if $dry_run; then
        printf '%s\n' "$1"
    else
        die "required package is unavailable (checked: $*)"
    fi
}

install_debian_dependencies() {
    local os_id os_like os_version major
    [[ -r /etc/os-release ]] || die 'cannot identify this distribution; use --no-deps'
    # shellcheck source=/dev/null
    os_id=$(. /etc/os-release; printf '%s' "${ID:-}")
    # shellcheck source=/dev/null
    os_like=$(. /etc/os-release; printf '%s' "${ID_LIKE:-}")
    # shellcheck source=/dev/null
    os_version=$(. /etc/os-release; printf '%s' "${VERSION_ID:-}")
    case " $os_id $os_like " in
        *' debian '*|*' ubuntu '*) ;;
        *) die 'automatic packages support Debian/Ubuntu only; install native prerequisites and use --no-deps' ;;
    esac
    major=${os_version%%.*}
    if [[ $major =~ ^[0-9]+$ ]]; then
        if [[ $os_id == debian ]] && ((10#$major < 13)); then
            die 'Debian 13 or newer is required for native hidapi >= 0.14; use --no-deps with upgraded prerequisites on older systems'
        fi
        if [[ $os_id == ubuntu ]] && ((10#$major < 24)); then
            die 'Ubuntu 24.04 or newer is required for this Qt6/QML workflow'
        fi
    fi
    if ! $dry_run; then
        command -v apt-get >/dev/null || die 'apt-get is required for automatic package installation'
        command -v apt-cache >/dev/null || die 'apt-cache is required for package discovery'
    fi
    require_root_command
    run "${root_command[@]}" env DEBIAN_FRONTEND=noninteractive \
        apt-get -o APT::Update::Error-Mode=any update
    local packages=(
        ca-certificates ccache cmake g++ git ninja-build pkg-config
        docbook-to-man fonts-open-sans markdown
        libavformat-dev libchromaprint-dev libebur128-dev libfaad-dev
        libfftw3-dev libflac-dev libgl1-mesa-dev libhidapi-dev libid3tag0-dev
        liblilv-dev libmad0-dev libmodplug-dev libmp3lame-dev libmsgsl-dev
        libopus-dev libopusfile-dev libpipewire-0.3-dev libportmidi-dev
        libprotobuf-dev libqt6opengl6-dev libqt6sql6-sqlite libqt6svg6-dev
        librubberband-dev libshout-idjc-dev libsndfile1-dev libsoundtouch-dev
        libspa-0.2-dev libsqlite3-dev libssl-dev libtag1-dev libudev-dev
        libupower-glib-dev libusb-1.0-0-dev libwavpack-dev lv2-dev
        portaudio19-dev protobuf-compiler qtkeychain-qt6-dev
        qt6-base-private-dev qt6-declarative-private-dev qt6-multimedia-dev qt6-translations-l10n
        qml6-module-qt5compat-graphicaleffects qml6-module-qtcore
        qml6-module-qtqml-workerscript qml6-module-qtquick-controls
        qml6-module-qtquick-dialogs qml6-module-qtquick-layouts
        qml6-module-qtquick-shapes qml6-module-qtquick-templates
        qml6-module-qtquick-window qml6-module-qt-labs-qmlmodels
        qml6-module-qt-labs-folderlistmodel qml6-module-qtmultimedia
    )
    packages+=("$(package_alias qt6-shadertools-dev libqt6shadertools6-dev)")
    packages+=("$(package_alias qt6-5compat-dev libqt6core5compat6-dev)")
    if $run_tests; then packages+=(libgmock-dev libgtest-dev); fi
    if available_package qt6-svg-plugins; then packages+=(qt6-svg-plugins); fi
    if available_package mold; then packages+=(mold); fi
    if available_package fonts-ubuntu; then
        packages+=(fonts-ubuntu)
    else
        printf 'Ubuntu fonts are unavailable in the configured repositories; keeping the existing Open Sans/system font fallback.\n'
    fi
    if dpkg-query -W -f='${Status}' jackd2 2>/dev/null | grep -q '^install ok installed$'; then
        packages+=(libjack-jackd2-dev)
    fi
    run "${root_command[@]}" env DEBIAN_FRONTEND=noninteractive \
        apt-get install -y --no-install-recommends -- "${packages[@]}"
}

needs_install_root=false
probe=$install_prefix
while [[ ! -e $probe && $probe != / ]]; do probe=$(dirname -- "$probe"); done
if [[ ! -d $probe || ! -w $probe ]]; then
    needs_install_root=true
    stage='installation privilege check'
    require_root_command
    if ((EUID != 0)) && ! $dry_run; then run "${root_command[@]}" true; fi
fi

if $install_dependencies; then
    stage='native dependency installation'
    install_debian_dependencies
fi

stage='configuration'
cmake_command=cmake
if ! $dry_run; then
    command -v cmake >/dev/null || die 'cmake is unavailable; install native dependencies first'
    cmake_command=$(command -v cmake)
    if $run_tests; then command -v ctest >/dev/null || die 'ctest is unavailable'; fi
fi
generator=()
if [[ ! -f "$build_dir/CMakeCache.txt" ]]; then
    if $dry_run || command -v ninja >/dev/null; then generator=(-G Ninja); fi
fi
test_option=ON
if ! $run_tests; then test_option=OFF; fi
run cmake -S "$repo_root" -B "$build_dir" "${generator[@]}" \
    -DCMAKE_BUILD_TYPE=RelWithDebInfo -DQT6=ON -DQML=ON \
    "-DBUILD_TESTING=$test_option" -DBUILD_BENCH=OFF \
    -DINSTALL_USER_UDEV_RULES=OFF -DDOWNLOAD_MANUAL=OFF \
    -DCMAKE_TLS_VERIFY=ON "-DCMAKE_INSTALL_PREFIX=$install_prefix"

stage='build'
run cmake --build "$build_dir" --parallel "$jobs"
if $run_tests; then
    stage='unit tests'
    run env "QT_QPA_PLATFORM=${QT_QPA_PLATFORM:-offscreen}" \
        ctest --test-dir "$build_dir" --parallel "$jobs" --output-on-failure --no-tests=error
fi

stage='installation'
if ! $needs_install_root; then
    run cmake --install "$build_dir"
else
    require_root_command
    run "${root_command[@]}" "$cmake_command" --install "$build_dir"
fi
stage='installed binary validation'
run env "QT_QPA_PLATFORM=${QT_QPA_PLATFORM:-offscreen}" "$install_prefix/bin/mixxx" --version
if $dry_run; then
    printf 'Dry run complete; no installation or build was performed.\n'
else
    printf 'Installed Mixxx. Start it with: %q\n' "$install_prefix/bin/mixxx"
    printf 'Installed-file manifest: %s/install_manifest.txt\n' "$build_dir"
fi
# End of autonomously generated AI-agent installer.
